  if(a==='unlock-vault'){const v=await unlockVault($('#vault-password').value);runtime.key=v.key;runtime.salt=v.salt;runtime.locked=false;await loadAll();await addActivity('Cofre desbloqueado');render();return}
  if(a==='lock-vault'){await addActivity('Cofre bloqueado');resetRuntime();runtime.vaultKnown=true;render();return}
  if(a==='toggle-sidebar'){runtime.sidebarOpen=!runtime.sidebarOpen;render();return}
