  if(a==='close-modal'){closeModal();return}
  if(a==='modal-backdrop'&&e.target===el){closeModal();return}
  if(a==='new-patient')return showPatientForm();
  if(a==='edit-patient')return showPatientForm(el.dataset.id);
  if(a==='save-patient'){const id=$('#p-id').value||uid('pat'),obj={...(patientById(id)||{}),id,name:sanitizeText($('#p-name').value),preferredName:sanitizeText($('#p-preferred').value),code:sanitizeText($('#p-code').value)||`PAC-${String(data.patients.length+1).padStart(3,'0')}`,status:$('#p-status').value,birthDate:$('#p-birth').value,phone:sanitizeText($('#p-phone').value),email:sanitizeText($('#p-email').value),modality:$('#p-modality').value,value:Number($('#p-value').value)||0,summary:sanitizeText($('#p-summary').value),communicationPreferences:{channel:$('#p-channel').value,whatsappConsent:$('#p-wa-consent').checked,emailConsent:$('#p-email-consent').checked,silentStart:'20:00',silentEnd:'08:00'},createdAt:patientById(id)?.createdAt||nowISO()};validatePatient(obj);await saveEntity('patients',obj,patientById(id)?'Paciente atualizado':'Paciente cadastrado');runtime.selectedPatientId=id;closeModal();render();toast('Cadastro salvo.','success');return}
