  if(a==='choose-patient')return showChoosePatient();
  if(a==='select-patient-modal'){runtime.selectedPatientId=el.dataset.id;closeModal();render();return}
  if(a==='patient-tab'){runtime.patientTab=el.dataset.tab;render();return}
  if(a==='enter-kiosk'){runtime.kioskPatientId=el.dataset.id;runtime.kioskUnlocked=true;await addActivity('Entrada no modo paciente',{patientId:el.dataset.id});render();return}
  if(a==='exit-kiosk'){modal('Saída protegida',`<p>Informe a senha do cofre para encerrar o modo paciente.</p><div class="field"><label>Senha</label><input id="kiosk-password" class="input" type="password"></div>`,`<button class="btn secondary" data-action="close-modal">Cancelar</button><button class="btn danger" data-action="confirm-exit-kiosk">Encerrar e bloquear</button>`);return}
