  if(a==='kiosk-material'){const m=data.materials.find(x=>x.id===el.dataset.id);modal(m?.title||'Material',`<p>${esc(m?.content||'')}</p>`,`<button class="btn" data-action="close-modal">Fechar</button>`);return}
