  if(a==='save-record-draft'||a==='finalize-record'){const p=selectedRequired(),draft={id:`draft_record_${p.id}`,patientId:p.id,title:sanitizeText($('#record-title').value),date:$('#record-date').value,text:sanitizeText($('#record-text').value),followup:sanitizeText($('#record-followup').value),updatedAt:nowISO()};assert(draft.text,'Digite o registro.');if(a==='save-record-draft'){await saveEntity('settings',draft,'Rascunho de registro salvo');toast('Rascunho salvo.','success')}else{assert(confirm(`Você está finalizando um registro para ${p.name}, código ${p.code||'sem código'}, referente a ${draft.date}. Confirmar?`),'Finalização cancelada.');const r={...draft,id:uid('rec'),status:'Finalizado',createdAt:nowISO(),addenda:[]};await saveEntity('records',r,'Registro finalizado');const old=data.settings.find(x=>x.id===draft.id);if(old)await removeEntity('settings',old.id,'Rascunho removido após finalização');toast('Registro finalizado.','success');render()}return}
