  if(a==='save-addendum'){const r=data.records.find(x=>x.id===$('#ad-record').value),reason=sanitizeText($('#ad-reason').value),text=sanitizeText($('#ad-text').value);assert(reason&&text,'Informe motivo e conteúdo.');r.addenda??=[];r.addenda.push({id:uid('ad'),at:nowISO(),reason,text});await saveEntity('records',r,'Adendo criado');closeModal();render();return}
  if(a==='save-note'){const p=selectedRequired(),title=sanitizeText($('#note-title').value),text=sanitizeText($('#note-text').value);assert(text,'Digite a nota.');assert(confirm(`Salvar nota técnica restrita para ${p.name}?`),'Operação cancelada.');await saveEntity('notes',{id:uid('note'),patientId:p.id,title,text,createdAt:nowISO()},'Nota restrita criada');render();toast('Nota restrita salva.','success');return}
